// Tema 10 · bloque 8 · Código Civil: medidas de apoyo a las personas con discapacidad (arts. 249-299) · IA estilo examen (10-ia-11051…)
const k = 'cc';
const Q = [
{k, a: 'art. 249', r: 'Medidas de apoyo: disposiciones generales', e: 'Las medidas de apoyo a las personas mayores de edad o menores emancipadas que las precisen para el adecuado ejercicio de su capacidad jurídica tendrán por finalidad permitir:',
 o: ['el desarrollo pleno de su personalidad y su desenvolvimiento jurídico en condiciones de igualdad.', 'la protección de su patrimonio y su representación legal.', 'el ejercicio de su capacidad por medio de un representante.', 'la sustitución de su voluntad cuando no pueda expresarla.'],
 t: 'tendrán por finalidad permitir el desarrollo pleno de su personalidad y su desenvolvimiento jurídico en condiciones de igualdad', p: 'Su finalidad es el desarrollo pleno de la personalidad en condiciones de igualdad.'},
{k, a: 'art. 249', r: 'Medidas de apoyo: disposiciones generales', e: 'Las medidas de apoyo de origen legal o judicial solo procederán:',
 o: ['en defecto o insuficiencia de la voluntad de la persona de que se trate.', 'cuando lo solicite el Ministerio Fiscal.', 'cuando exista un diagnóstico médico de discapacidad.', 'cuando la persona sea mayor de sesenta y cinco años.'],
 t: 'Las de origen legal o judicial solo procederán en defecto o insuficiencia de la voluntad de la persona de que se trate', p: 'Solo en defecto o insuficiencia de la voluntad de la persona.'},
{k, a: 'art. 249', r: 'Medidas de apoyo: disposiciones generales', e: 'Todas las medidas de apoyo deberán ajustarse a los principios de:',
 o: ['necesidad y proporcionalidad.', 'legalidad y subsidiariedad.', 'proporcionalidad y temporalidad.', 'intervención mínima y control judicial.'],
 t: 'Todas ellas deberán ajustarse a los principios de necesidad y proporcionalidad', p: 'Necesidad y proporcionalidad.'},
{k, a: 'art. 249', r: 'Medidas de apoyo: disposiciones generales', e: 'Las personas que presten apoyo deberán actuar atendiendo a la voluntad, deseos y preferencias de quien lo requiera. Igualmente procurarán que la persona con discapacidad pueda desarrollar su propio proceso de toma de decisiones, y fomentarán que pueda ejercer su capacidad jurídica:',
 o: ['con menos apoyo en el futuro.', 'con la asistencia permanente del curador.', 'con autorización judicial.', 'con el consentimiento de sus familiares.'],
 t: 'fomentarán que la persona con discapacidad pueda ejercer su capacidad jurídica con menos apoyo en el futuro', p: 'Con menos apoyo en el futuro.'},
{k, a: 'art. 249', r: 'Medidas de apoyo: funciones representativas', e: 'En casos excepcionales, cuando, pese a haberse hecho un esfuerzo considerable, no sea posible determinar la voluntad, deseos y preferencias de la persona, las medidas de apoyo:',
 o: ['podrán incluir funciones representativas.', 'se sustituirán por una tutela.', 'quedarán en suspenso.', 'deberán ser aprobadas por el Ministerio Fiscal.'],
 t: 'las medidas de apoyo podrán incluir funciones representativas', p: 'Podrán incluir funciones representativas.'},
{k, a: 'art. 250', r: 'Medidas de apoyo: clases', e: 'Las medidas de apoyo para el ejercicio de la capacidad jurídica de las personas que lo precisen son, además de las de naturaleza voluntaria:',
 o: ['la guarda de hecho, la curatela y el defensor judicial.', 'la tutela, la curatela y el defensor judicial.', 'la guarda de hecho, la tutela y la curatela.', 'la patria potestad prorrogada, la curatela y el defensor judicial.'],
 t: 'son, además de las de naturaleza voluntaria, la guarda de hecho, la curatela y el defensor judicial', p: 'Guarda de hecho, curatela y defensor judicial.'},
{k, a: 'art. 250', r: 'Medidas de apoyo: clases', e: 'La guarda de hecho es una medida informal de apoyo que puede existir cuando:',
 o: ['no haya medidas voluntarias o judiciales que se estén aplicando eficazmente.', 'no exista curador nombrado.', 'lo autorice el Ministerio Fiscal.', 'la persona no pueda expresar su voluntad.'],
 t: 'La guarda de hecho es una medida informal de apoyo que puede existir cuando no haya medidas voluntarias o judiciales que se estén aplicando eficazmente', p: 'Cuando no haya medidas voluntarias o judiciales aplicándose eficazmente.'},
{k, a: 'art. 250', r: 'Medidas de apoyo: clases', e: 'La curatela es una medida formal de apoyo que se aplicará:',
 o: ['a quienes precisen el apoyo de modo continuado.', 'a quienes precisen el apoyo de modo ocasional.', 'a quienes carezcan de familiares.', 'a quienes no puedan expresar su voluntad.'],
 t: 'La curatela es una medida formal de apoyo que se aplicará a quienes precisen el apoyo de modo continuado', p: 'A quienes precisen apoyo de modo continuado.'},
{k, a: 'art. 250', r: 'Medidas de apoyo: clases', e: 'El nombramiento de defensor judicial como medida formal de apoyo procederá cuando la necesidad de apoyo se precise:',
 o: ['de forma ocasional, aunque sea recurrente.', 'de modo continuado.', 'de forma urgente.', 'de forma transitoria, sin posibilidad de repetirse.'],
 t: 'El nombramiento de defensor judicial como medida formal de apoyo procederá cuando la necesidad de apoyo se precise de forma ocasional, aunque sea recurrente', p: 'De forma ocasional, aunque sea recurrente.'},
{k, a: 'art. 250', r: 'Medidas de apoyo: clases', e: 'No podrán ejercer ninguna de las medidas de apoyo quienes, en virtud de una relación contractual:',
 o: ['presten servicios asistenciales, residenciales o de naturaleza análoga a la persona que precisa el apoyo.', 'hayan sido socios o administradores de la persona con discapacidad.', 'sean acreedores de la persona que precisa el apoyo.', 'tengan relación laboral con los familiares de la persona.'],
 t: 'No podrán ejercer ninguna de las medidas de apoyo quienes, en virtud de una relación contractual, presten servicios asistenciales, residenciales o de naturaleza análoga a la persona que precisa el apoyo', p: 'Quienes presten servicios asistenciales o residenciales por relación contractual.'},
{k, a: 'art. 251', r: 'Medidas de apoyo: prohibiciones', e: 'Se prohíbe a quien desempeñe alguna medida de apoyo recibir liberalidades de la persona que precisa el apoyo o de sus causahabientes, mientras que no se haya aprobado definitivamente su gestión, salvo que se trate de:',
 o: ['regalos de costumbre o bienes de escaso valor.', 'bienes inmuebles de escaso valor.', 'donaciones autorizadas por el Juez.', 'legados testamentarios.'],
 t: 'mientras que no se haya aprobado definitivamente su gestión, salvo que se trate de regalos de costumbre o bienes de escaso valor', p: 'Regalos de costumbre o bienes de escaso valor.'},
{k, a: 'art. 251', r: 'Medidas de apoyo: prohibiciones', e: 'En las medidas de apoyo voluntarias las prohibiciones del apoyo no resultarán de aplicación cuando:',
 o: ['el otorgante las haya excluido expresamente en el documento de constitución de dichas medidas.', 'lo autorice el Ministerio Fiscal.', 'lo autorice el letrado de la Administración de Justicia.', 'la persona con discapacidad lo manifieste verbalmente.'],
 t: 'En las medidas de apoyo voluntarias estas prohibiciones no resultarán de aplicación cuando el otorgante las haya excluido expresamente en el documento de constitución de dichas medidas', p: 'Cuando el otorgante las excluya expresamente en el documento.'},
{k, a: 'art. 252', r: 'Disposiciones a título gratuito', e: 'El que disponga de bienes a título gratuito en favor de una persona necesitada de apoyo podrá establecer las reglas de administración y disposición de aquellos. Las facultades no conferidas al administrador corresponderán:',
 o: ['al favorecido por la disposición de los bienes, que las ejercitará, en su caso, con el apoyo que proceda.', 'al curador de la persona con discapacidad.', 'al Ministerio Fiscal.', 'a la autoridad judicial.'],
 t: 'Las facultades no conferidas al administrador corresponderán al favorecido por la disposición de los bienes, que las ejercitará, en su caso, con el apoyo que proceda', p: 'Al favorecido, con el apoyo que proceda.'},
{k, a: 'art. 253', r: 'Apoyo urgente', e: 'Cuando una persona se encuentre en una situación que exija apoyo para el ejercicio de su capacidad jurídica de modo urgente y carezca de un guardador de hecho, el apoyo se prestará de modo provisional por la entidad pública. La entidad dará conocimiento de la situación al Ministerio Fiscal en el plazo de:',
 o: ['veinticuatro horas.', 'cuarenta y ocho horas.', 'tres días.', 'setenta y dos horas.'],
 t: 'La entidad dará conocimiento de la situación al Ministerio Fiscal en el plazo de veinticuatro horas', p: 'El plazo es de veinticuatro horas.'},
{k, a: 'art. 254', r: 'Apoyo a menores próximos a la mayoría de edad', e: 'Cuando se prevea razonablemente en los dos años anteriores a la mayoría de edad que un menor sujeto a patria potestad o a tutela pueda, después de alcanzada aquella, precisar de apoyo, la autoridad judicial podrá acordar la procedencia de la medida de apoyo a petición:',
 o: ['del menor, de los progenitores, del tutor o del Ministerio Fiscal.', 'del menor y de los progenitores, exclusivamente.', 'del Ministerio Fiscal y de la Entidad Pública, exclusivamente.', 'del tutor y del curador.'],
 t: 'la autoridad judicial podrá acordar, a petición del menor, de los progenitores, del tutor o del Ministerio Fiscal, si lo estima necesario, la procedencia de la adopción de la medida de apoyo que corresponda', p: 'Menor, progenitores, tutor o Ministerio Fiscal.'},
{k, a: 'art. 254', r: 'Apoyo a menores próximos a la mayoría de edad', e: 'Las medidas de apoyo para cuando concluya la minoría de edad se adoptarán si el mayor de dieciséis años:',
 o: ['no ha hecho sus propias previsiones para cuando alcance la mayoría de edad.', 'ha cumplido los dieciséis años y lo solicita.', 'ha sido declarado en situación de desamparo.', 'carece de progenitores.'],
 t: 'Estas medidas se adoptarán si el mayor de dieciséis años no ha hecho sus propias previsiones para cuando alcance la mayoría de edad', p: 'Si el mayor de dieciséis años no ha hecho previsiones propias.'},
{k, a: 'art. 255', r: 'Medidas voluntarias de apoyo', e: 'Cualquier persona mayor de edad o menor emancipada en previsión o apreciación de la concurrencia de circunstancias que puedan dificultarle el ejercicio de su capacidad jurídica en igualdad de condiciones con las demás, podrá prever o acordar medidas de apoyo relativas a su persona o bienes:',
 o: ['en escritura pública.', 'en documento privado.', 'ante el letrado de la Administración de Justicia.', 'ante el Juez.'],
 t: 'podrá prever o acordar en escritura pública medidas de apoyo relativas a su persona o bienes', p: 'En escritura pública.'},
{k, a: 'art. 255', r: 'Medidas voluntarias de apoyo', e: 'El Notario autorizante comunicará de oficio y sin dilación el documento público que contenga las medidas de apoyo:',
 o: ['al Registro Civil para su constancia en el registro individual del otorgante.', 'al Registro de la Propiedad para su inscripción.', 'al Ministerio Fiscal para su control.', 'al Juzgado de Primera Instancia.'],
 t: 'El Notario autorizante comunicará de oficio y sin dilación el documento público que contenga las medidas de apoyo al Registro Civil para su constancia en el registro individual del otorgante', p: 'Al Registro Civil para su constancia.'},
{k, a: 'art. 255', r: 'Medidas voluntarias de apoyo', e: 'Solo en defecto o por insuficiencia de las medidas de naturaleza voluntaria, y a falta de guarda de hecho que suponga apoyo suficiente, podrá la autoridad judicial:',
 o: ['adoptar otras supletorias o complementarias.', 'sustituir las medidas voluntarias por una curatela.', 'nombrar un defensor judicial.', 'anular las medidas voluntarias.'],
 t: 'Solo en defecto o por insuficiencia de estas medidas de naturaleza voluntaria, y a falta de guarda de hecho que suponga apoyo suficiente, podrá la autoridad judicial adoptar otras supletorias o complementarias', p: 'Adoptar otras supletorias o complementarias.'},
{k, a: 'art. 256', r: 'Poderes y mandatos preventivos', e: 'El poderdante podrá incluir una cláusula que estipule que:',
 o: ['el poder subsista si en el futuro precisa apoyo en el ejercicio de su capacidad.', 'el poder se extinga si precisa apoyo en el ejercicio de su capacidad.', 'el poder se transforme en curatela si precisa apoyo.', 'el apoderado sea sustituido por un curador.'],
 t: 'El poderdante podrá incluir una cláusula que estipule que el poder subsista si en el futuro precisa apoyo en el ejercicio de su capacidad', p: 'Que el poder subsista.'},
{k, a: 'art. 257', r: 'Poderes y mandatos preventivos', e: 'El poderdante podrá otorgar poder solo para el supuesto de que en el futuro precise apoyo en el ejercicio de su capacidad. En este caso, para acreditar que se ha producido la situación de necesidad de apoyo:',
 o: ['se estará a las previsiones del poderdante.', 'se estará a lo que determine el Juez.', 'bastará la declaración del apoderado.', 'se necesitará resolución judicial.'],
 t: 'En este caso, para acreditar que se ha producido la situación de necesidad de apoyo se estará a las previsiones del poderdante', p: 'Se estará a las previsiones del poderdante.'},
{k, a: 'art. 257', r: 'Poderes y mandatos preventivos', e: 'Para garantizar el cumplimiento de las previsiones del poderdante se otorgará, si fuera preciso, acta notarial que, además del juicio del Notario, incorpore:',
 o: ['un informe pericial en el mismo sentido.', 'un informe del Ministerio Fiscal.', 'el consentimiento de los familiares.', 'una autorización judicial.'],
 t: 'se otorgará, si fuera preciso, acta notarial que, además del juicio del Notario, incorpore un informe pericial en el mismo sentido', p: 'Un informe pericial en el mismo sentido.'},
{k, a: 'art. 258', r: 'Poderes y mandatos preventivos', e: 'Los poderes preventivos mantendrán su vigencia pese a la constitución de otras medidas de apoyo en favor del poderdante, tanto si estas han sido establecidas judicialmente como si:',
 o: ['han sido previstas por el propio interesado.', 'han sido propuestas por el Ministerio Fiscal.', 'han sido acordadas por la Entidad Pública.', 'han sido otorgadas ante notario.'],
 t: 'mantendrán su vigencia pese a la constitución de otras medidas de apoyo en favor del poderdante, tanto si estas han sido establecidas judicialmente como si han sido previstas por el propio interesado', p: 'Si han sido previstas por el propio interesado.'},
{k, a: 'art. 258', r: 'Poderes y mandatos preventivos', e: 'Cuando el poder preventivo se hubiere otorgado a favor del cónyuge o de la pareja de hecho del poderdante, el cese de la convivencia producirá su extinción automática, salvo que:',
 o: ['medie voluntad contraria del otorgante o que el cese venga determinado por el internamiento de este.', 'lo solicite el apoderado.', 'lo autorice el Ministerio Fiscal.', 'existan hijos menores comunes.'],
 t: 'el cese de la convivencia producirá su extinción automática, salvo que medie voluntad contraria del otorgante o que el cese venga determinado por el internamiento de este', p: 'Salvo voluntad contraria del otorgante o cese por su internamiento.'},
{k, a: 'art. 258', r: 'Poderes y mandatos preventivos', e: 'Cualquier persona legitimada para instar el procedimiento de provisión de apoyos y el curador, si lo hubiere, podrán solicitar judicialmente la extinción de los poderes preventivos, si en el apoderado concurre alguna de las causas previstas para la remoción del curador, salvo que:',
 o: ['el poderdante hubiera previsto otra cosa.', 'el apoderado sea cónyuge del poderdante.', 'el Ministerio Fiscal se oponga.', 'el poder sea anterior a la medida de apoyo.'],
 t: 'podrán solicitar judicialmente la extinción de los poderes preventivos, si en el apoderado concurre alguna de las causas previstas para la remoción del curador, salvo que el poderdante hubiera previsto otra cosa', p: 'Salvo que el poderdante haya previsto otra cosa.'},
{k, a: 'art. 259', r: 'Poderes y mandatos preventivos', e: 'Cuando el poder contenga cláusula de subsistencia para el caso de que el poderdante precise apoyo o se conceda solo para ese supuesto y, en ambos casos, comprenda todos los negocios del otorgante, el apoderado, sobrevenida la situación de necesidad de apoyo, quedará sujeto:',
 o: ['a las reglas aplicables a la curatela en todo aquello no previsto en el poder, salvo que el poderdante haya determinado otra cosa.', 'a las reglas de la tutela en todo aquello no previsto en el poder.', 'a las reglas de la guarda de hecho.', 'a las instrucciones del Ministerio Fiscal.'],
 t: 'quedará sujeto a las reglas aplicables a la curatela en todo aquello no previsto en el poder, salvo que el poderdante haya determinado otra cosa', p: 'A las reglas de la curatela.'},
{k, a: 'art. 260', r: 'Poderes y mandatos preventivos', e: 'Los poderes preventivos habrán de otorgarse:',
 o: ['en escritura pública.', 'en documento privado con firma legitimada.', 'ante el Juez.', 'en acta ante el letrado de la Administración de Justicia.'],
 t: 'Los poderes preventivos a que se refieren los artículos anteriores habrán de otorgarse en escritura pública', p: 'En escritura pública.'},
{k, a: 'art. 261', r: 'Poderes y mandatos preventivos', e: 'El ejercicio de las facultades representativas será personal, sin perjuicio de la posibilidad de encomendar la realización de uno o varios actos concretos a terceras personas. Aquellas facultades que tengan por objeto la protección de la persona:',
 o: ['no serán delegables.', 'serán delegables con autorización judicial.', 'serán delegables en el cónyuge.', 'serán delegables a terceras personas.'],
 t: 'Aquellas facultades que tengan por objeto la protección de la persona no serán delegables', p: 'No serán delegables.'},
{k, a: 'art. 262', r: 'Poderes y mandatos preventivos', e: 'Lo dispuesto en el capítulo de las medidas voluntarias de apoyo se aplicará igualmente:',
 o: ['al caso de mandato sin poder.', 'al caso de mandato con poder.', 'al caso de las donaciones.', 'al caso de los poderes generales.'],
 t: 'Lo dispuesto en este capítulo se aplicará igualmente al caso de mandato sin poder', p: 'Al mandato sin poder.'},
{k, a: 'art. 263', r: 'Guarda de hecho', e: 'Quien viniere ejerciendo adecuadamente la guarda de hecho de una persona con discapacidad continuará en el desempeño de su función incluso si existen medidas de apoyo de naturaleza voluntaria o judicial, siempre que:',
 o: ['estas no se estén aplicando eficazmente.', 'lo autorice el Ministerio Fiscal.', 'lo consienta la persona con discapacidad.', 'sean complementarias de la guarda.'],
 t: 'siempre que estas no se estén aplicando eficazmente', p: 'Siempre que las otras medidas no se apliquen eficazmente.'},
{k, a: 'art. 264', r: 'Guarda de hecho', e: 'Cuando, excepcionalmente, se requiera la actuación representativa del guardador de hecho, este habrá de obtener la autorización para realizarla a través del correspondiente expediente de jurisdicción voluntaria, en el que se oirá:',
 o: ['a la persona con discapacidad.', 'al Ministerio Fiscal, exclusivamente.', 'a los familiares de la persona con discapacidad.', 'a la entidad pública competente.'],
 t: 'este habrá de obtener la autorización para realizarla a través del correspondiente expediente de jurisdicción voluntaria, en el que se oirá a la persona con discapacidad', p: 'Se oye a la persona con discapacidad.'},
{k, a: 'art. 264', r: 'Guarda de hecho', e: 'No será necesaria autorización judicial cuando el guardador solicite una prestación económica a favor de la persona con discapacidad, siempre que esta:',
 o: ['no suponga un cambio significativo en la forma de vida de la persona.', 'no exceda de un importe determinado.', 'sea inferior al salario mínimo.', 'sea comunicada al Ministerio Fiscal.'],
 t: 'No será necesaria autorización judicial cuando el guardador solicite una prestación económica a favor de la persona con discapacidad, siempre que esta no suponga un cambio significativo en la forma de vida de la persona', p: 'Siempre que no suponga un cambio significativo en su forma de vida.'},
{k, a: 'art. 265', r: 'Guarda de hecho', e: 'A través de un expediente de jurisdicción voluntaria, la autoridad judicial podrá requerir al guardador en cualquier momento, de oficio, a solicitud del Ministerio Fiscal o a instancia de cualquier interesado, para que:',
 o: ['informe de su actuación, y establecer las salvaguardias que estime necesarias.', 'rinda cuentas en el plazo de tres meses.', 'preste fianza.', 'se someta a la curatela.'],
 t: 'la autoridad judicial podrá requerir al guardador en cualquier momento, de oficio, a solicitud del Ministerio Fiscal o a instancia de cualquier interesado, para que informe de su actuación, y establecer las salvaguardias que estime necesarias', p: 'Para que informe de su actuación y se establezcan salvaguardias.'},
{k, a: 'art. 266', r: 'Guarda de hecho', e: 'El guardador tiene derecho al reembolso de los gastos justificados y a la indemnización por los daños derivados de la guarda, a cargo:',
 o: ['de los bienes de la persona a la que presta apoyo.', 'de la entidad pública.', 'del Estado.', 'de los familiares de la persona.'],
 t: 'El guardador tiene derecho al reembolso de los gastos justificados y a la indemnización por los daños derivados de la guarda, a cargo de los bienes de la persona a la que presta apoyo', p: 'A cargo de los bienes de la persona con apoyo.'},
{k, a: 'art. 267', r: 'Guarda de hecho: extinción', e: 'La guarda de hecho se extingue. Señale la INCORRECTA:',
 o: ['Cuando transcurran dos años desde su constitución.', 'Cuando la persona a quien se preste apoyo solicite que este se organice de otro modo.', 'Cuando desaparezcan las causas que la motivaron.', 'Cuando, a solicitud del Ministerio Fiscal o de quien se interese por ejercer el apoyo, la autoridad judicial lo considere conveniente.'],
 t: 'La guarda de hecho se extingue: 1.º Cuando la persona a quien se preste apoyo solicite que este se organice de otro modo. 2.º Cuando desaparezcan las causas que la motivaron', p: 'No se extingue por el mero transcurso de dos años.'},
{k, a: 'art. 267', r: 'Guarda de hecho: extinción', e: 'Cuando el guardador desista de su actuación, deberá ponerlo previamente en conocimiento:',
 o: ['de la entidad pública que en el respectivo territorio tenga encomendada las funciones de promoción de la autonomía y asistencia a las personas con discapacidad.', 'del Ministerio Fiscal.', 'de la autoridad judicial.', 'del Registro Civil.'],
 t: 'Cuando el guardador desista de su actuación, en cuyo caso deberá ponerlo previamente en conocimiento de la entidad pública que en el respectivo territorio tenga encomendada las funciones de promoción de la autonomía y asistencia a las personas con discapacidad', p: 'De la entidad pública competente.'},
{k, a: 'art. 268', r: 'Curatela: disposiciones generales', e: 'Las medidas de apoyo adoptadas judicialmente serán revisadas periódicamente en un plazo máximo de:',
 o: ['tres años.', 'dos años.', 'cinco años.', 'seis años.'],
 t: 'Las medidas de apoyo adoptadas judicialmente serán revisadas periódicamente en un plazo máximo de tres años', p: 'Máximo tres años.'},
{k, a: 'art. 268', r: 'Curatela: disposiciones generales', e: 'La autoridad judicial podrá, de manera excepcional y motivada, establecer un plazo de revisión de las medidas de apoyo superior al general, que no podrá exceder de:',
 o: ['seis años.', 'cinco años.', 'ocho años.', 'diez años.'],
 t: 'establecer un plazo de revisión superior que no podrá exceder de seis años', p: 'No podrá exceder de seis años.'},
{k, a: 'art. 268', r: 'Curatela: disposiciones generales', e: 'Sin perjuicio de las revisiones periódicas, las medidas de apoyo adoptadas judicialmente se revisarán, en todo caso:',
 o: ['ante cualquier cambio en la situación de la persona que pueda requerir una modificación de dichas medidas.', 'cada año.', 'cuando lo solicite el curador.', 'cuando lo solicite el Ministerio Fiscal.'],
 t: 'las medidas de apoyo adoptadas judicialmente se revisarán, en todo caso, ante cualquier cambio en la situación de la persona que pueda requerir una modificación de dichas medidas', p: 'Ante cualquier cambio en la situación de la persona.'},
{k, a: 'art. 269', r: 'Curatela: constitución', e: 'La autoridad judicial constituirá la curatela mediante resolución motivada cuando:',
 o: ['no exista otra medida de apoyo suficiente para la persona con discapacidad.', 'lo solicite la persona con discapacidad.', 'lo solicite el Ministerio Fiscal.', 'la persona carezca de familiares.'],
 t: 'La autoridad judicial constituirá la curatela mediante resolución motivada cuando no exista otra medida de apoyo suficiente para la persona con discapacidad', p: 'Cuando no exista otra medida de apoyo suficiente.'},
{k, a: 'art. 269', r: 'Curatela: constitución', e: 'Sólo en los casos excepcionales en los que resulte imprescindible por las circunstancias de la persona con discapacidad, la autoridad judicial determinará en resolución motivada:',
 o: ['los actos concretos en los que el curador habrá de asumir la representación de la persona con discapacidad.', 'los actos que quedan prohibidos a la persona con discapacidad.', 'la sustitución del curador por un tutor.', 'las facultades patrimoniales del curador.'],
 t: 'la autoridad judicial determinará en resolución motivada los actos concretos en los que el curador habrá de asumir la representación de la persona con discapacidad', p: 'Los actos concretos en que el curador representa.'},
{k, a: 'art. 269', r: 'Curatela: constitución', e: 'En ningún caso podrá incluir la resolución judicial por la que se constituye la curatela:',
 o: ['la mera privación de derechos.', 'la designación del curador.', 'las medidas de control.', 'la fijación de los actos representativos.'],
 t: 'En ningún caso podrá incluir la resolución judicial la mera privación de derechos', p: 'La mera privación de derechos.'},
{k, a: 'art. 270', r: 'Curatela: control', e: 'Sin perjuicio de las revisiones periódicas de las resoluciones de curatela, podrá recabar en cualquier momento la información que considere necesaria a fin de garantizar el buen funcionamiento de la curatela:',
 o: ['el Ministerio Fiscal.', 'el letrado de la Administración de Justicia.', 'la entidad pública.', 'los familiares de la persona con apoyo.'],
 t: 'Sin perjuicio de las revisiones periódicas de estas resoluciones, el Ministerio Fiscal podrá recabar en cualquier momento la información que considere necesaria a fin de garantizar el buen funcionamiento de la curatela', p: 'El Ministerio Fiscal.'},
{k, a: 'art. 271', r: 'Autocuratela', e: 'Cualquier persona mayor de edad o menor emancipada, en previsión de la concurrencia de circunstancias que puedan dificultarle el ejercicio de su capacidad jurídica en igualdad de condiciones con las demás, podrá proponer en escritura pública:',
 o: ['el nombramiento o la exclusión de una o varias personas determinadas para el ejercicio de la función de curador.', 'el nombramiento de un tutor y de un defensor judicial.', 'la exclusión de la curatela para el supuesto de discapacidad.', 'el nombramiento de un único curador para todos los actos.'],
 t: 'podrá proponer en escritura pública el nombramiento o la exclusión de una o varias personas determinadas para el ejercicio de la función de curador', p: 'Nombramiento o exclusión de una o varias personas como curador.'},
{k, a: 'art. 272', r: 'Autocuratela', e: 'La propuesta de nombramiento y demás disposiciones voluntarias vincularán a la autoridad judicial al constituir la curatela. No obstante, la autoridad judicial podrá prescindir total o parcialmente de esas disposiciones voluntarias, siempre mediante resolución motivada, si existen:',
 o: ['circunstancias graves desconocidas por la persona que las estableció o alteración de las causas expresadas por ella o que presumiblemente tuvo en cuenta en sus disposiciones.', 'circunstancias económicas desfavorables para el curador propuesto.', 'razones de oportunidad apreciadas por el Ministerio Fiscal.', 'circunstancias que permitan nombrar a un familiar de la persona.'],
 t: 'si existen circunstancias graves desconocidas por la persona que las estableció o alteración de las causas expresadas por ella o que presumiblemente tuvo en cuenta en sus disposiciones', p: 'Circunstancias graves desconocidas o alteración de las causas.'},
{k, a: 'art. 273', r: 'Autocuratela', e: 'Si al establecer la autocuratela se propone el nombramiento de sustitutos al curador y no se concreta el orden de la sustitución, será preferido el propuesto en el documento posterior. Si se proponen varios en el mismo documento, será preferido:',
 o: ['el propuesto en primer lugar.', 'el propuesto en último lugar.', 'el de mayor edad.', 'el que designe la autoridad judicial.'],
 t: 'Si se proponen varios en el mismo documento, será preferido el propuesto en primer lugar', p: 'El propuesto en primer lugar.'},
{k, a: 'art. 274', r: 'Autocuratela', e: 'Se podrá delegar en el cónyuge o en otra persona la elección del curador de entre los relacionados:',
 o: ['en escritura pública por la persona interesada.', 'en documento privado por el cónyuge.', 'en el expediente judicial.', 'en el testamento del interesado.'],
 t: 'Se podrá delegar en el cónyuge o en otra persona la elección del curador de entre los relacionados en escritura pública por la persona interesada', p: 'En escritura pública por la persona interesada.'},
{k, a: 'art. 275.2', r: 'Curatela: nombramiento', e: 'No podrán ser curadores. Señale la INCORRECTA:',
 o: ['Quienes sean mayores de setenta años.', 'Quienes hayan sido excluidos por la persona que precise apoyo.', 'Quienes por resolución judicial estuvieran privados o suspendidos en el ejercicio de la patria potestad o, total o parcialmente, de los derechos de guarda y protección.', 'Quienes hubieren sido legalmente removidos de una tutela, curatela o guarda anterior.'],
 t: 'No podrán ser curadores: 1.º Quienes hayan sido excluidos por la persona que precise apoyo. 2.º Quienes por resolución judicial estuvieran privados o suspendidos en el ejercicio de la patria potestad o, total o parcialmente, de los derechos de guarda y protección. 3.º Quienes hubieren sido legalmente removidos de una tutela, curatela o guarda anterior', p: 'La edad no es causa de inhabilidad.'},
{k, a: 'art. 275.3', r: 'Curatela: nombramiento', e: 'La autoridad judicial no podrá nombrar curador, salvo circunstancias excepcionales debidamente motivadas, a las personas siguientes. Señale la INCORRECTA:',
 o: ['A quien sea familiar de la persona que precise apoyo.', 'A quien haya sido condenado por cualquier delito que haga suponer fundadamente que no desempeñará bien la curatela.', 'A quien tenga conflicto de intereses con la persona que precise apoyo.', 'Al administrador que hubiese sido sustituido en sus facultades de administración durante la tramitación del procedimiento concursal.'],
 t: 'La autoridad judicial no podrá nombrar curador, salvo circunstancias excepcionales debidamente motivadas, a las personas siguientes: 1.º A quien haya sido condenado por cualquier delito que haga suponer fundadamente que no desempeñará bien la curatela. 2.º A quien tenga conflicto de intereses con la persona que precise apoyo', p: 'Ser familiar no impide el nombramiento.'},
{k, a: 'art. 276', r: 'Curatela: orden de nombramiento', e: 'En defecto de propuesta, la autoridad judicial nombrará curador, en primer lugar:',
 o: ['al cónyuge, o a quien se encuentre en una situación de hecho asimilable, siempre que convivan con la persona que precisa el apoyo.', 'al hijo o descendiente que conviva con la persona.', 'al progenitor o, en su defecto, ascendiente.', 'a la persona que designe el Ministerio Fiscal.'],
 t: '1.º Al cónyuge, o a quien se encuentre en una situación de hecho asimilable, siempre que convivan con la persona que precisa el apoyo', p: 'En primer lugar el cónyuge o situación asimilable que conviva.'},
{k, a: 'art. 276', r: 'Curatela: orden de nombramiento', e: 'En defecto de propuesta, la autoridad judicial nombrará curador al hijo o descendiente. Si fueran varios:',
 o: ['será preferido el que de ellos conviva con la persona que precisa el apoyo.', 'será preferido el de mayor edad.', 'será preferido el de menor edad.', 'decidirá el Ministerio Fiscal.'],
 t: '2.º Al hijo o descendiente. Si fueran varios, será preferido el que de ellos conviva con la persona que precisa el apoyo', p: 'Se prefiere al que conviva con la persona.'},
{k, a: 'art. 276', r: 'Curatela: orden de nombramiento', e: 'En el orden legal de nombramiento de curador, tras el progenitor o ascendiente, se nombrará:',
 o: ['a la persona o personas que el cónyuge o la pareja conviviente o los progenitores hubieran dispuesto en testamento o documento público.', 'a quien estuviera actuando como guardador de hecho.', 'al hermano, pariente o allegado que conviva con la persona.', 'a una persona jurídica sin ánimo de lucro.'],
 t: '4.º A la persona o personas que el cónyuge o la pareja conviviente o los progenitores hubieran dispuesto en testamento o documento público', p: 'Cuarto: la persona dispuesta por cónyuge, pareja o progenitores.'},
{k, a: 'art. 276', r: 'Curatela: orden de nombramiento', e: 'La autoridad judicial podrá alterar el orden legal de nombramiento del curador:',
 o: ['una vez oída la persona que precise apoyo.', 'a petición del Ministerio Fiscal.', 'a solicitud del cónyuge.', 'previo informe médico.'],
 t: 'La autoridad judicial podrá alterar el orden del apartado anterior, una vez oída la persona que precise apoyo', p: 'Una vez oída la persona que precise apoyo.'},
{k, a: 'art. 277', r: 'Curatela: pluralidad de curadores', e: 'Se puede proponer el nombramiento de más de un curador si la voluntad y necesidades de la persona que precisa el apoyo lo justifican. En particular, podrán separarse como cargos distintos:',
 o: ['los de curador de la persona y curador de los bienes.', 'los de curador y defensor judicial.', 'los de curador y guardador de hecho.', 'los de curador y tutor.'],
 t: 'En particular, podrán separarse como cargos distintos los de curador de la persona y curador de los bienes', p: 'Curador de la persona y curador de los bienes.'},
{k, a: 'art. 278', r: 'Curatela: remoción', e: 'Serán removidos de la curatela los que, después del nombramiento, incurran en una causa legal de inhabilidad, o se conduzcan mal en su desempeño por incumplimiento de los deberes propios del cargo, por notoria ineptitud de su ejercicio o cuando, en su caso, surgieran:',
 o: ['problemas de convivencia graves y continuados con la persona a la que prestan apoyo.', 'diferencias de criterio con el Ministerio Fiscal.', 'problemas económicos del curador.', 'discrepancias con los familiares de la persona.'],
 t: 'o cuando, en su caso, surgieran problemas de convivencia graves y continuados con la persona a la que prestan apoyo', p: 'Problemas de convivencia graves y continuados.'},
{k, a: 'art. 278', r: 'Curatela: remoción', e: 'La autoridad judicial podrá decretar la remoción del curador de oficio o a solicitud de la persona a cuyo favor se estableció el apoyo o del Ministerio Fiscal, mediante:',
 o: ['expediente de jurisdicción voluntaria.', 'juicio verbal.', 'procedimiento ordinario.', 'resolución administrativa.'],
 t: 'podrá decretar la remoción del curador mediante expediente de jurisdicción voluntaria', p: 'Mediante expediente de jurisdicción voluntaria.'},
{k, a: 'art. 278', r: 'Curatela: remoción', e: 'Durante la tramitación del expediente de remoción la autoridad judicial podrá suspender al curador en sus funciones y, de considerarlo necesario:',
 o: ['acordará el nombramiento de un defensor judicial.', 'nombrará a un tutor.', 'asumirá directamente la curatela.', 'encomendará la curatela a la entidad pública.'],
 t: 'Durante la tramitación del expediente de remoción la autoridad judicial podrá suspender al curador en sus funciones y, de considerarlo necesario, acordará el nombramiento de un defensor judicial', p: 'Nombrará un defensor judicial.'},
{k, a: 'art. 279', r: 'Curatela: excusa', e: 'El interesado que alegue causa de excusa del cargo de curador deberá hacerlo dentro del plazo de:',
 o: ['quince días a contar desde que tuviera conocimiento del nombramiento.', 'diez días a contar desde que tuviera conocimiento del nombramiento.', 'treinta días a contar desde la notificación del nombramiento.', 'un mes desde su toma de posesión.'],
 t: 'El interesado que alegue causa de excusa deberá hacerlo dentro del plazo de quince días a contar desde que tuviera conocimiento del nombramiento', p: 'Quince días desde que conozca el nombramiento.'},
{k, a: 'art. 279', r: 'Curatela: excusa', e: 'Si la causa de excusa fuera sobrevenida el curador podrá alegarla:',
 o: ['en cualquier momento.', 'en el plazo de quince días desde que sobrevenga.', 'en el plazo de un mes desde que sobrevenga.', 'solo con autorización judicial.'],
 t: 'Si la causa fuera sobrevenida podrá hacerlo en cualquier momento', p: 'En cualquier momento.'},
{k, a: 'art. 279', r: 'Curatela: excusa', e: 'Mientras la autoridad judicial resuelva acerca de la excusa, el nombrado estará obligado a ejercer su función. Si no lo hiciera y fuera necesaria una actuación de apoyo:',
 o: ['se procederá a nombrar un defensor judicial que sustituya al curador, quedando el sustituido responsable de los gastos ocasionados por la excusa, si esta fuera rechazada.', 'se suspenderá la curatela hasta que se resuelva la excusa.', 'actuará el Ministerio Fiscal en su sustitución.', 'se nombrará un tutor interino.'],
 t: 'Si no lo hiciera y fuera necesaria una actuación de apoyo, se procederá a nombrar un defensor judicial que sustituya al curador, quedando el sustituido responsable de los gastos ocasionados por la excusa, si esta fuera rechazada', p: 'Se nombra defensor judicial y el sustituido responde de los gastos si se rechaza la excusa.'},
{k, a: 'art. 279', r: 'Curatela: excusa', e: 'Las personas jurídicas privadas podrán excusarse de la curatela cuando:',
 o: ['carezcan de medios suficientes para el adecuado desempeño de la curatela o las condiciones de ejercicio de la curatela no sean acordes con sus fines estatutarios.', 'tengan menos de diez años de antigüedad.', 'sean fundaciones.', 'existan otras personas físicas disponibles.'],
 t: 'Las personas jurídicas privadas podrán excusarse cuando carezcan de medios suficientes para el adecuado desempeño de la curatela o las condiciones de ejercicio de la curatela no sean acordes con sus fines estatutarios', p: 'Falta de medios o condiciones no acordes con sus fines.'},
{k, a: 'art. 280', r: 'Curatela: excusa', e: 'El curador nombrado en atención a una disposición testamentaria que se excuse de la curatela por cualquier causa:',
 o: ['perderá lo que en consideración al nombramiento le hubiere dejado el testador.', 'conservará lo que el testador le hubiere dejado.', 'perderá la mitad de lo que le hubiere dejado el testador.', 'devolverá lo percibido con intereses.'],
 t: 'El curador nombrado en atención a una disposición testamentaria que se excuse de la curatela por cualquier causa, perderá lo que en consideración al nombramiento le hubiere dejado el testador', p: 'Pierde lo que le dejó el testador.'},
{k, a: 'art. 281', r: 'Curatela: retribución', e: 'El curador tiene derecho a una retribución, siempre que el patrimonio de la persona con discapacidad lo permita, así como al reembolso de los gastos justificados y a la indemnización de los daños sufridos:',
 o: ['sin culpa por su parte en el ejercicio de su función.', 'por su actuación diligente en cualquier caso.', 'con ocasión de la función, aunque medie culpa.', 'con autorización judicial.'],
 t: 'a la indemnización de los daños sufridos sin culpa por su parte en el ejercicio de su función', p: 'Si los daños se sufren sin culpa por su parte.'},
{k, a: 'art. 281', r: 'Curatela: retribución', e: 'No concurrirá causa de excusa cuando el desempeño de los apoyos haya sido encomendado a:',
 o: ['entidad pública.', 'persona jurídica privada.', 'fundación.', 'familiar de la persona.'],
 t: 'No concurrirá causa de excusa cuando el desempeño de los apoyos haya sido encomendado a entidad pública', p: 'A una entidad pública.'},
{k, a: 'art. 282', r: 'Curatela: ejercicio', e: 'El curador tomará posesión de su cargo ante:',
 o: ['el letrado de la Administración de Justicia.', 'el Juez de Primera Instancia.', 'el Ministerio Fiscal.', 'el Encargado del Registro Civil.'],
 t: 'El curador tomará posesión de su cargo ante el letrado de la Administración de Justicia', p: 'Ante el letrado de la Administración de Justicia.'},
{k, a: 'art. 282', r: 'Curatela: ejercicio', e: 'Una vez en el ejercicio de la curatela, el curador estará obligado a mantener contacto personal con la persona a la que va a prestar apoyo y a:',
 o: ['desempeñar las funciones encomendadas con la diligencia debida.', 'rendir cuentas cada mes.', 'informar semestralmente al Ministerio Fiscal.', 'visitarla al menos una vez al mes.'],
 t: 'estará obligado a mantener contacto personal con la persona a la que va a prestar apoyo y a desempeñar las funciones encomendadas con la diligencia debida', p: 'Desempeñar sus funciones con la diligencia debida.'},
{k, a: 'art. 283', r: 'Curatela: impedimento o conflicto', e: 'Cuando quien desempeñe la curatela esté impedido de modo transitorio para actuar en un caso concreto, o cuando exista un conflicto de intereses ocasional entre él y la persona a quien preste apoyo, nombrará un defensor judicial que lo sustituya:',
 o: ['el letrado de la Administración de Justicia.', 'el Juez.', 'el Ministerio Fiscal.', 'la entidad pública.'],
 t: 'el letrado de la Administración de Justicia nombrará un defensor judicial que lo sustituya', p: 'El letrado de la Administración de Justicia.'},
{k, a: 'art. 283', r: 'Curatela: impedimento o conflicto', e: 'Si la situación de impedimento o conflicto fuera prolongada o reiterada, la autoridad judicial podrá reorganizar el funcionamiento de la curatela, e incluso:',
 o: ['proceder al nombramiento de un nuevo curador.', 'extinguir la curatela.', 'sustituirla por una tutela.', 'nombrar un defensor judicial permanente.'],
 t: 'podrá reorganizar el funcionamiento de la curatela, e incluso proceder al nombramiento de un nuevo curador', p: 'Incluso nombrar un nuevo curador.'},
{k, a: 'art. 284', r: 'Curatela: fianza', e: 'Cuando la autoridad judicial lo considere necesario por concurrir razones excepcionales, podrá exigir al curador:',
 o: ['la constitución de fianza que asegure el cumplimiento de sus obligaciones.', 'la constitución de hipoteca sobre sus bienes.', 'la contratación de un seguro de responsabilidad.', 'un aval bancario.'],
 t: 'podrá exigir al curador la constitución de fianza que asegure el cumplimiento de sus obligaciones y determinará la modalidad y cuantía de la misma', p: 'La constitución de fianza.'},
{k, a: 'art. 285', r: 'Curatela: inventario', e: 'El curador con facultades representativas estará obligado a hacer inventario del patrimonio de la persona en cuyo favor se ha establecido el apoyo dentro del plazo de:',
 o: ['sesenta días, a contar desde aquel en que hubiese tomado posesión de su cargo.', 'treinta días, a contar desde su nombramiento.', 'noventa días, a contar desde su nombramiento.', 'sesenta días, a contar desde su aceptación.'],
 t: 'estará obligado a hacer inventario del patrimonio de la persona en cuyo favor se ha establecido el apoyo dentro del plazo de sesenta días, a contar desde aquel en que hubiese tomado posesión de su cargo', p: 'Sesenta días desde la toma de posesión.'},
{k, a: 'art. 285', r: 'Curatela: inventario', e: 'El inventario del patrimonio se formará:',
 o: ['ante el letrado de la Administración de Justicia, con citación de las personas que estime conveniente.', 'ante notario, con citación del Ministerio Fiscal.', 'ante el Juez, con asistencia de dos testigos.', 'ante el Encargado del Registro Civil.'],
 t: 'El inventario se formará ante el letrado de la Administración de Justicia, con citación de las personas que estime conveniente', p: 'Ante el letrado de la Administración de Justicia.'},
{k, a: 'art. 286', r: 'Curatela: créditos', e: 'En el caso de que el curador no incluya en el inventario los créditos que tenga contra la persona a la que presta apoyo, se entenderá:',
 o: ['que renuncia a ellos.', 'que los reserva para su reclamación posterior.', 'que los compensa con su retribución.', 'que los cede al Ministerio Fiscal.'],
 t: 'En el caso de que el curador no incluya en el inventario los créditos que tenga contra la persona a la que presta apoyo, se entenderá que renuncia a ellos', p: 'Se entiende que renuncia a ellos.'},
{k, a: 'art. 287', r: 'Curatela: autorización judicial', e: 'El curador que ejerza funciones de representación de la persona que precisa el apoyo necesita autorización judicial para los actos que determine la resolución y, en todo caso, para enajenar o gravar bienes inmuebles o dar inmuebles en arrendamiento por término inicial que exceda de:',
 o: ['seis años.', 'cinco años.', 'diez años.', 'tres años.'],
 t: 'dar inmuebles en arrendamiento por término inicial que exceda de seis años', p: 'Seis años.'},
{k, a: 'art. 287', r: 'Curatela: autorización judicial', e: 'La enajenación de determinados bienes de la persona con medidas de apoyo por el curador representativo se realizará mediante:',
 o: ['venta directa salvo que el Tribunal considere que es necesaria la enajenación en subasta judicial para mejor y plena garantía de los derechos e intereses de su titular.', 'subasta judicial salvo que el Tribunal autorice la venta directa.', 'subasta pública en todo caso.', 'venta directa, sin posibilidad de subasta.'],
 t: 'La enajenación de los bienes mencionados en este párrafo se realizará mediante venta directa salvo que el Tribunal considere que es necesaria la enajenación en subasta judicial para mejor y plena garantía de los derechos e intereses de su titular', p: 'Venta directa, salvo que el Tribunal considere necesaria la subasta.'},
{k, a: 'art. 287', r: 'Curatela: autorización judicial', e: 'El curador representativo necesita autorización judicial para disponer a título gratuito de bienes o derechos de la persona con medidas de apoyo, salvo:',
 o: ['los que tengan escasa relevancia económica y carezcan de especial significado personal o familiar.', 'los de valor inferior a mil euros.', 'los que sean bienes muebles.', 'los que autorice el Ministerio Fiscal.'],
 t: 'Disponer a título gratuito de bienes o derechos de la persona con medidas de apoyo, salvo los que tengan escasa relevancia económica y carezcan de especial significado personal o familiar', p: 'Salvo los de escasa relevancia económica y sin especial significado.'},
{k, a: 'art. 287', r: 'Curatela: autorización judicial', e: 'Para renunciar derechos, así como transigir o someter a arbitraje cuestiones relativas a los intereses de la persona cuya curatela ostenta, no se precisará la autorización judicial para:',
 o: ['el arbitraje de consumo.', 'el arbitraje de equidad.', 'la transacción extrajudicial.', 'la renuncia de derechos de escasa cuantía.'],
 t: 'No se precisará la autorización judicial para el arbitraje de consumo', p: 'Para el arbitraje de consumo.'},
{k, a: 'art. 287', r: 'Curatela: autorización judicial', e: 'El curador representativo necesita autorización judicial para aceptar sin beneficio de inventario cualquier herencia o:',
 o: ['repudiar esta o las liberalidades.', 'aceptar donaciones de escaso valor.', 'aceptar legados de bienes muebles.', 'renunciar a la retribución.'],
 t: 'Aceptar sin beneficio de inventario cualquier herencia o repudiar esta o las liberalidades', p: 'Repudiar herencia o liberalidades.'},
{k, a: 'art. 287', r: 'Curatela: autorización judicial', e: 'El curador representativo necesita autorización judicial para interponer demanda en nombre de la persona a la que presta apoyo, salvo en los asuntos urgentes o de escasa cuantía. No será precisa la autorización judicial cuando:',
 o: ['la persona con discapacidad inste la revisión de la resolución judicial en que previamente se le hubiesen determinado los apoyos.', 'el curador actúe en defensa de sus propios intereses.', 'lo solicite el Ministerio Fiscal.', 'la demanda se interponga ante el Juzgado de Paz.'],
 t: 'No será precisa la autorización judicial cuando la persona con discapacidad inste la revisión de la resolución judicial en que previamente se le hubiesen determinado los apoyos', p: 'Cuando se inste la revisión de la resolución de apoyos.'},
{k, a: 'art. 288', r: 'Curatela: autorización genérica', e: 'La autoridad judicial, cuando lo considere adecuado para garantizar la voluntad, deseos y preferencias de la persona con discapacidad, podrá autorizar al curador la realización:',
 o: ['de una pluralidad de actos de la misma naturaleza o referidos a la misma actividad económica, especificando las circunstancias y características fundamentales de dichos actos.', 'de cualquier acto de administración ordinaria.', 'de una pluralidad de actos de distinta naturaleza.', 'de actos futuros sin límite alguno.'],
 t: 'podrá autorizar al curador la realización de una pluralidad de actos de la misma naturaleza o referidos a la misma actividad económica, especificando las circunstancias y características fundamentales de dichos actos', p: 'Pluralidad de actos de la misma naturaleza o actividad económica.'},
{k, a: 'art. 289', r: 'Curatela: partición', e: 'No necesitarán autorización judicial la partición de herencia o la división de cosa común realizada por el curador representativo, pero:',
 o: ['una vez practicadas requerirán aprobación judicial.', 'requerirán aprobación del Ministerio Fiscal.', 'requerirán aprobación notarial.', 'requerirán comunicación al Registro Civil.'],
 t: 'No necesitarán autorización judicial la partición de herencia o la división de cosa común realizada por el curador representativo, pero una vez practicadas requerirán aprobación judicial', p: 'Requieren aprobación judicial una vez practicadas.'},
{k, a: 'art. 290', r: 'Curatela: audiencia', e: 'Antes de autorizar o aprobar cualquiera de los actos que requieren autorización judicial, la autoridad judicial oirá:',
 o: ['al Ministerio Fiscal y a la persona con medidas de apoyo y recabará los informes que le sean solicitados o estime pertinentes.', 'al curador y al Ministerio Fiscal.', 'a los familiares y a la entidad pública.', 'a la persona con medidas de apoyo, exclusivamente.'],
 t: 'la autoridad judicial oirá al Ministerio Fiscal y a la persona con medidas de apoyo y recabará los informes que le sean solicitados o estime pertinentes', p: 'Se oye al Ministerio Fiscal y a la persona con medidas de apoyo.'},
{k, a: 'art. 291', r: 'Curatela: extinción', e: 'La curatela se extingue de pleno derecho por:',
 o: ['la muerte o declaración de fallecimiento de la persona con medidas de apoyo.', 'la muerte del curador.', 'la mayoría de edad de la persona.', 'la declaración de ausencia de la persona.'],
 t: 'La curatela se extingue de pleno derecho por la muerte o declaración de fallecimiento de la persona con medidas de apoyo', p: 'Muerte o declaración de fallecimiento de la persona apoyada.'},
{k, a: 'art. 291', r: 'Curatela: extinción', e: 'La curatela se extingue por resolución judicial cuando:',
 o: ['ya no sea precisa esta medida de apoyo o cuando se adopte una forma de apoyo más adecuada para la persona sometida a curatela.', 'lo solicite el curador.', 'transcurran seis años desde su constitución.', 'lo solicite el cónyuge.'],
 t: 'la curatela se extingue por resolución judicial cuando ya no sea precisa esta medida de apoyo o cuando se adopte una forma de apoyo más adecuada para la persona sometida a curatela', p: 'Cuando ya no es precisa o hay un apoyo más adecuado.'},
{k, a: 'art. 292', r: 'Curatela: rendición final de cuentas', e: 'El curador, al cesar en sus funciones, deberá rendir ante la autoridad judicial la cuenta general justificada de su administración en el plazo de tres meses:',
 o: ['prorrogables por el tiempo que fuere necesario si concurre justa causa.', 'prorrogables por otros tres meses.', 'improrrogables.', 'prorrogables por el Ministerio Fiscal.'],
 t: 'deberá rendir ante ella la cuenta general justificada de su administración en el plazo de tres meses, prorrogables por el tiempo que fuere necesario si concurre justa causa', p: 'Tres meses prorrogables por justa causa.'},
{k, a: 'art. 292', r: 'Curatela: rendición final de cuentas', e: 'La acción para exigir la rendición de la cuenta general justificada del curador prescribe:',
 o: ['a los cinco años, contados desde la terminación del plazo establecido para efectuarla.', 'a los tres años, contados desde la rendición de cuentas.', 'a los cinco años, contados desde el cese del curador.', 'a los diez años, contados desde la muerte de la persona.'],
 t: 'La acción para exigir la rendición de esta cuenta prescribe a los cinco años, contados desde la terminación del plazo establecido para efectuarla', p: 'Cinco años desde la terminación del plazo.'},
{k, a: 'art. 293', r: 'Curatela: rendición de cuentas', e: 'Si el saldo de la cuenta general es en contra del curador, devengará el interés legal:',
 o: ['una vez transcurridos los tres meses siguientes a la aprobación de la cuenta.', 'desde la aprobación de la cuenta.', 'desde el cese del curador.', 'una vez transcurridos seis meses desde la aprobación de la cuenta.'],
 t: 'Si es en contra del curador, devengará el interés legal una vez transcurridos los tres meses siguientes a la aprobación de la cuenta', p: 'A los tres meses siguientes a la aprobación.'},
{k, a: 'art. 294', r: 'Curatela: responsabilidad', e: 'La acción para reclamar la responsabilidad del curador por los daños que hubiese causado por su culpa o negligencia prescribe:',
 o: ['a los tres años contados desde la rendición final de cuentas.', 'a los cinco años contados desde el cese del curador.', 'a los tres años contados desde el cese del curador.', 'al año contado desde la rendición final de cuentas.'],
 t: 'La acción para reclamar esta responsabilidad prescribe a los tres años contados desde la rendición final de cuentas', p: 'Tres años desde la rendición final de cuentas.'},
{k, a: 'art. 295', r: 'Defensor judicial de personas con discapacidad', e: 'Se nombrará un defensor judicial de las personas con discapacidad en los casos siguientes. Señale la INCORRECTA:',
 o: ['Cuando la persona con discapacidad cumpla los sesenta años.', 'Cuando exista conflicto de intereses entre la persona con discapacidad y la que haya de prestarle apoyo.', 'Cuando, durante la tramitación de la excusa alegada por el curador, la autoridad judicial lo considere necesario.', 'Cuando la persona con discapacidad requiera el establecimiento de medidas de apoyo de carácter ocasional, aunque sea recurrente.'],
 t: '2.º Cuando exista conflicto de intereses entre la persona con discapacidad y la que haya de prestarle apoyo. 3.º Cuando, durante la tramitación de la excusa alegada por el curador, la autoridad judicial lo considere necesario', p: 'La edad no es causa de nombramiento.'},
{k, a: 'art. 295', r: 'Defensor judicial de personas con discapacidad', e: 'Una vez oída la persona con discapacidad, la autoridad judicial nombrará defensor judicial:',
 o: ['a quien sea más idóneo para respetar, comprender e interpretar la voluntad, deseos y preferencias de aquella.', 'al familiar más próximo.', 'a quien designe el Ministerio Fiscal.', 'al curador sustituto.'],
 t: 'Una vez oída la persona con discapacidad, la autoridad judicial nombrará defensor judicial a quien sea más idóneo para respetar, comprender e interpretar la voluntad, deseos y preferencias de aquella', p: 'A quien sea más idóneo para respetar, comprender e interpretar su voluntad.'},
{k, a: 'art. 296', r: 'Defensor judicial de personas con discapacidad', e: 'No se nombrará defensor judicial si el apoyo se ha encomendado a más de una persona, salvo que:',
 o: ['ninguna pueda actuar o la autoridad judicial motivadamente considere necesario el nombramiento.', 'lo solicite el Ministerio Fiscal.', 'lo pidan los familiares.', 'una de ellas sea una persona jurídica.'],
 t: 'No se nombrará defensor judicial si el apoyo se ha encomendado a más de una persona, salvo que ninguna pueda actuar o la autoridad judicial motivadamente considere necesario el nombramiento', p: 'Salvo que ninguna pueda actuar o el Juez lo considere necesario.'},
{k, a: 'art. 297', r: 'Defensor judicial de personas con discapacidad', e: 'Serán aplicables al defensor judicial las causas de inhabilidad, excusa y remoción del curador, así como las obligaciones que a este se atribuyen:',
 o: ['de conocer y respetar la voluntad, deseos y preferencias de la persona a la que se preste apoyo.', 'de rendir cuentas mensualmente.', 'de informar al Ministerio Fiscal cada seis meses.', 'de hacer inventario en sesenta días.'],
 t: 'así como las obligaciones que a este se atribuyen de conocer y respetar la voluntad, deseos y preferencias de la persona a la que se preste apoyo', p: 'Conocer y respetar la voluntad, deseos y preferencias.'},
{k, a: 'art. 298', r: 'Defensor judicial de personas con discapacidad', e: 'En el nombramiento se podrá dispensar al defensor judicial de la venta en subasta pública, fijando un precio mínimo, y de:',
 o: ['la aprobación judicial posterior de los actos.', 'la rendición de cuentas.', 'la autorización previa del Ministerio Fiscal.', 'la prestación de fianza.'],
 t: 'En el nombramiento se podrá dispensar al defensor judicial de la venta en subasta pública, fijando un precio mínimo, y de la aprobación judicial posterior de los actos', p: 'De la aprobación judicial posterior de los actos.'},
{k, a: 'art. 298', r: 'Defensor judicial de personas con discapacidad', e: 'El defensor judicial, una vez realizada su gestión:',
 o: ['deberá rendir cuentas de ella.', 'quedará exento de rendir cuentas.', 'deberá rendir cuentas solo si lo exige el Ministerio Fiscal.', 'deberá rendir cuentas en el plazo de un año.'],
 t: 'El defensor judicial, una vez realizada su gestión, deberá rendir cuentas de ella', p: 'Debe rendir cuentas de su gestión.'},
{k, a: 'art. 299', r: 'Responsabilidad por daños', e: 'La persona con discapacidad responderá por los daños causados a otros, de acuerdo con el capítulo relativo a la responsabilidad extracontractual, sin perjuicio de:',
 o: ['lo establecido en materia de responsabilidad extracontractual respecto a otros posibles responsables.', 'la responsabilidad solidaria del curador.', 'la exención de responsabilidad por la discapacidad.', 'la responsabilidad subsidiaria del Estado.'],
 t: 'La persona con discapacidad responderá por los daños causados a otros, de acuerdo con el Capítulo II del Título XVI del Libro Cuarto, sin perjuicio de lo establecido en materia de responsabilidad extracontractual respecto a otros posibles responsables', p: 'Sin perjuicio de otros posibles responsables.'},
];
